{"query":"
  query EventQuery($slug: String!) {
    event(slug: $slug) {
      id
      name
      numEntrants
      teamRosterSize {
        minPlayers
        maxPlayers
      }
      videogame {
        id
        name
      }
      phases {
        id
        name
        phaseOrder
      }
      phaseGroups {
        id
        displayIdentifier
        bracketType
        phase {
          id
        }
      }
      tournament {
        id
        name
        slug
        startAt
        endAt
        city
        addrState
        countryCode
        isOnline
      }
    }
  }
","variables":{"slug":"tournament/akh-presents-ssbu-shrimp-tank-3-shrimply-the-best/event/ultimate-singles"}}
